import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';

class RegisterScreen extends StatefulWidget{const RegisterScreen({super.key});@override State<RegisterScreen> createState()=>_RegisterScreenState();}
class _RegisterScreenState extends State<RegisterScreen>{final email=TextEditingController(),pass=TextEditingController(),name=TextEditingController();bool loading=false;
Future<void> go()async{if(email.text.trim().isEmpty||pass.text.length<6)return;setState(()=>loading=true);try{final r=await FirebaseAuth.instance.createUserWithEmailAndPassword(email:email.text.trim(),password:pass.text);await FirebaseFirestore.instance.collection('users').doc(r.user!.uid).set({'email':r.user!.email,'displayName':name.text.trim(),'role':'BUYER','createdAt':FieldValue.serverTimestamp()});if(mounted)Navigator.pop(context);}on FirebaseAuthException catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.message??'Daftar gagal')));}finally{if(mounted)setState(()=>loading=false);}}
@override Widget build(BuildContext c)=>Scaffold(backgroundColor:const Color(0xFFF4F8FF),appBar:AppBar(backgroundColor:Colors.transparent,title:const Text('Buat akun')),body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:Container(constraints:const BoxConstraints(maxWidth:440),padding:const EdgeInsets.all(24),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(28)),child:Column(children:[const Icon(Icons.storefront_rounded,size:58,color:Color(0xFF126BFF)),const SizedBox(height:14),const Text('Daftar Nusopa.Mart',style:TextStyle(fontSize:24,fontWeight:FontWeight.w800)),const SizedBox(height:24),TextField(controller:name,decoration:const InputDecoration(labelText:'Nama')),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email')),TextField(controller:pass,obscureText:true,decoration:const InputDecoration(labelText:'Password minimal 6 karakter')),const SizedBox(height:20),FilledButton(onPressed:loading?null:go,style:FilledButton.styleFrom(minimumSize:const Size.fromHeight(52)),child:Text(loading?'Membuat akun...':'DAFTAR SEKARANG'))]))));}
}